package energy;/** * EU能量存储接口 * <p> * 定义了EU能量系统的基本操作，包括能量的存储、提取和查询。 * 所有使用EU能量的方块实体都应实现此接口。 * </p> */public interface EUEnergyStorage {    /**     * 向存储中添加能量     *     * @param maxReceive 最大接收量 (EU)     * @param simulate   如果为true，仅模拟不实际改变     * @return 实际接收的能量值     */    long receiveEnergy(long maxReceive, boolean simulate);    /**     * 从存储中提取能量     *     * @param maxExtract 最大提取量 (EU)     * @param simulate   如果为true，仅模拟不实际改变     * @return 实际提取的能量值     */    long extractEnergy(long maxExtract, boolean simulate);    /**     * 获取当前存储的能量     *     * @return 当前能量值 (EU)     */    long getEnergyStored();    /**     * 获取最大存储容量     *     * @return 最大能量值 (EU)     */    long getMaxEnergyStored();    /**     * 检查是否可以接收能量     *     * @return 如果可以接收返回true     */    default boolean canReceive() {        return true;    }    /**     * 检查是否可以提取能量     *     * @return 如果可以提取返回true     */    default boolean canExtract() {        return true;    }    /**     * 检查存储是否已满     *     * @return 如果已满返回true     */    default boolean isFull() {        return getEnergyStored() >= getMaxEnergyStored();    }    /**     * 检查存储是否为空     *     * @return 如果为空返回true     */    default boolean isEmpty() {        return getEnergyStored() <= 0;    }    /**     * 获取能量填充比例     *     * @return 0.0到1.0之间的填充比例     */    default double getEnergyPercentage() {        long max = getMaxEnergyStored();        if (max <= 0) return 0;        return (double) getEnergyStored() / max;    }    /**     * 获取运行电压等级     *     * @return 电压等级     */    EUVoltage getVoltage();    /**     * 获取最大接收/输出速率     *     * @return 最大传输速率 (EU/t)     */    long getMaxTransferRate();}